<?php require __DIR__.'/../partials/dashboard-head.php';?><div class="dash-head"><h1>Nhà cung cấp</h1><p style="color:#667085">Quản lý thông tin nhà cung cấp phục vụ đơn mua và công nợ.</p></div><?php foreach(getFlash() as $x):?><div class="alert alert-<?=e($x['type'])?>"><?=e($x['message'])?></div><?php endforeach;?><?php if($canManage):?><div class="panel" style="padding:16px;margin-bottom:16px"><h2 style="font-size:16px">Thêm nhà cung cấp</h2><form method="post" action="/admin/suppliers" style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px"><?=csrfField()?><div class="form-group"><label>Tên *</label><input name="name" required maxlength="160"></div><div class="form-group"><label>Điện thoại</label><input name="phone" maxlength="10" pattern="0[35789][0-9]{8}" placeholder="03, 05, 07, 08 hoặc 09"></div><div class="form-group"><label>Email</label><input name="email" type="email" maxlength="254"></div><div class="form-group"><label>Mã số thuế</label><input name="tax_code" maxlength="40"></div><div class="form-group" style="grid-column:span 2"><label>Địa chỉ</label><input name="address" maxlength="300"></div><div><button class="btn btn-navy">Tạo nhà cung cấp</button></div></form></div><?php endif;?><div class="panel"><table class="tbl"><thead><tr><th>Mã</th><th>Nhà cung cấp</th><th>Điện thoại</th><th>Email</th><th>Mã số thuế</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['code'])?></td><td><strong><?=e($i['name'])?></strong><div class="fs-11 text-muted"><?=e($i['address']?:'-')?></div></td><td><?=e($i['phone']?:'-')?></td><td><?=e($i['email']?:'-')?></td><td><?=e($i['tax_code']?:'-')?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5" style="padding:25px;text-align:center">Chưa có nhà cung cấp.</td></tr><?php endif;?></tbody></table></div><?php require __DIR__.'/../partials/dashboard-foot.php';?>